-- Installed TW MasterData SHA-256: 730d2aea3e7138d0212b64d80d7fe13e2c72ff03086944f3c8d2e325b4b592cc

CREATE TABLE public.tower_definitions (name TEXT PRIMARY KEY, data JSONB NOT NULL);
CREATE TABLE public.player_tower_states (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    tower_code BIGINT NOT NULL,
    checked_at BIGINT NOT NULL DEFAULT 0,
    PRIMARY KEY (player_id,tower_code)
);
CREATE TABLE public.player_tower_floors (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    tower_code BIGINT NOT NULL,
    floor INTEGER NOT NULL CHECK (floor>0),
    clear_count INTEGER NOT NULL DEFAULT 0 CHECK (clear_count>=0),
    continue_round_index INTEGER NOT NULL DEFAULT 0 CHECK (continue_round_index>=0),
    first_cleared_at BIGINT,
    used_characters JSONB NOT NULL DEFAULT '[]'::jsonb,
    used_magic_items JSONB NOT NULL DEFAULT '[]'::jsonb,
    PRIMARY KEY (player_id,tower_code,floor)
);
CREATE TABLE public.player_tower_battles (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    unique_id BYTEA NOT NULL CHECK (octet_length(unique_id)=16),
    tower_code BIGINT NOT NULL,
    floor INTEGER NOT NULL,
    starting_round_index INTEGER NOT NULL,
    start_hash TEXT NOT NULL,
    parties BYTEA NOT NULL,
    state TEXT NOT NULL CHECK (state IN ('active','settled','abandoned')),
    result_hash TEXT,
    response BYTEA,
    PRIMARY KEY (player_id,unique_id)
);
CREATE UNIQUE INDEX player_tower_active_battle ON public.player_tower_battles(player_id)
    WHERE state='active';
CREATE TABLE public.player_tower_rewards (
    player_id TEXT NOT NULL REFERENCES public.players(player_id) ON DELETE CASCADE,
    tower_code BIGINT NOT NULL,
    kind TEXT NOT NULL CHECK (kind IN ('first','daily')),
    period BIGINT NOT NULL,
    floor INTEGER NOT NULL,
    received_at BIGINT NOT NULL,
    PRIMARY KEY (player_id,tower_code,kind,period)
);
